{"language":"js","summary":"Survey the repo layout, git state and memory for the audit","code":"const sh = async (c)=> (await Bun.$`sh -c ${c}`.nothrow().text());
const r = await parallel([
 ()=>sh('pwd; git rev-parse --show-toplevel 2>&1; git log --oneline -5 2>&1; git status --short | head'),
 ()=>sh('git ls-files 2>/dev/null | sed -E "s/.*\\.//" | sort | uniq -c | sort -rn | head -15'),
 ()=>sh('git ls-files 2>/dev/null | awk -F/ "{print \\$1}" | sort | uniq -c | sort -rn | head -30'),
 ()=>sh('ls -la; ls ~/.omo 2>/dev/null | head; ls .omo 2>/dev/null'),
 ()=>sh('git ls-files 2>/dev/null | xargs wc -l 2>/dev/null | tail -1'),
]);
r.forEach(x=>print(x+'\n---'));"}

{"code":"const sh = async (c)=> (await Bun.$`sh -c ${c}`.nothrow().text());
